$equal=$s->decidir(8,'2026-09',$partial['latest_version'],'value-equal-paid','SERVICOS',array_replace($input,['valor'=>'20,00']));
$equalItem=array_values(array_filter($equal['revisao']['financeiro_servicos']['itens_analisados'],fn($i)=>$i['identidade']===$item['identidade']))[0];
checkValue($equalItem['situacao']==='QUITADO' && isset($equalItem['ajuste_valor']),'Ajuste igual ao já pago encerra o saldo e mantém restauração disponível');
